-- (9) 文書テンプレート ---------------------------------------------------
-- 差し込み項目（{{会社名}} など）を、会議や転換型証券の回次の値に置き換えて文書を作る。文面は、デモ用の例。

insert into document_templates (id, "organizationId", kind, title, status, body, notes) values
  ('d7000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', 'shareholder_notice', '株主総会の招集通知', 'reviewed', E'{{作成日}}\n\n株主各位\n\n{{本店所在地}}\n{{会社名}}\n{{代表者}}\n\n{{会議の名称}}招集ご通知\n\n拝啓　平素より格別のご高配を賜り、厚く御礼申し上げます。\nさて、当社{{会議の名称}}を下記のとおり開催いたしますので、ご出席くださいますようご通知申し上げます。\n当日ご出席いただけない場合は、同封の委任状に賛否をご表示のうえ、ご返送くださいますようお願い申し上げます。\n敬具\n\n記\n\n1. 日時　{{開催日時}}\n2. 場所　{{開催場所}}\n3. 会議の目的事項\n　報告事項\n{{報告事項}}\n　決議事項\n{{決議事項}}\n4. 議案の内容\n{{議案の内容}}\n\n以上', 'デモ用の例です。委任状を同封しない場合は、本文の 3 行目を直してください。'),
  ('d7000000-0000-0000-0000-000000000002', '11111111-1111-1111-1111-111111111111', 'shareholder_minutes', '株主総会議事録', 'draft', E'{{会議の名称}}議事録\n\n1. 開催の日時　{{開催日時}}\n2. 開催の場所　{{開催場所}}\n3. 議決権を行使することができる株主の数　{{株主の総数}}名\n4. 議決権を行使することができる株主の議決権の数　{{議決権の総数}}個\n5. 出席した株主の数（委任状による出席を含む）　{{出席株主数}}名\n6. 出席した株主の議決権の数　{{出席議決権数}}個\n7. 出席した役員　{{出席した役員}}\n8. 議長　{{議長}}\n9. 議事録の作成に係る職務を行った取締役　{{議事録の作成者}}\n\n議事の経過の要領およびその結果\n\n議長は、開会を宣し、上記のとおり本総会が適法に成立した旨を述べ、議事に入った。\n\n{{議案と結果}}\n\n以上をもって本総会の議事をすべて終了したので、議長は閉会を宣した。\n上記の議事の経過の要領およびその結果を明確にするため、本議事録を作成する。\n\n{{作成日}}\n{{会社名}}　{{会議の名称}}\n議事録作成者　{{議事録の作成者}}', ''),
  ('d7000000-0000-0000-0000-000000000003', '11111111-1111-1111-1111-111111111111', 'convertible_terms', 'J-KISS の条件のまとめ', 'reviewed', E'{{回次の名称}}　条件のまとめ\n\n作成日: {{作成日}}\n発行会社: {{会社名}}（{{本店所在地}}）\n代表者: {{代表者}}\n\n1. 証券の種類　{{証券の種類}}\n2. 評価上限額（バリュエーションキャップ）　金{{評価上限額}}円（{{評価上限額の基準}}）\n3. ディスカウント　{{ディスカウント率}}%（次回の資金調達の 1 株あたり発行価額に {{転換価額の乗率}} を乗じた額と、評価上限額による額の、低い方が転換価額）\n4. 適格資金調達の金額　金{{適格資金調達の金額}}円以上\n5. 発行日（割当日）　{{発行日}}\n6. 転換期限　{{転換期限}}\n7. 投資家と投資額（{{投資家の数}}名、合計 金{{投資額の合計}}円）\n{{投資家の一覧}}\n\n発行のあとの手続き\n- 新株予約権原簿に、新株予約権者と、新株予約権の内容・数を記載する。\n- 発行の登記を申請する（期限: {{登記の期限}}。割当日から 2 週間以内）。\n\nこの表は、台帳に登録した条件を並べたものです。投資契約書・発行要項と食い違うときは、契約書に従ってください。', '');

